//! 🧪️ Genuine captured aliases survive every paid prefix and receive actual supplied context deltas once.
use semio_framework_value_testing_allocator as _;
use semio_framework_job::*;
use semio_framework_value::{ValueError,ValueRefusalKind};
use semio_framework_async::CancelTokenRetirement;
use semio_framework_value::{RetainedAllocationEffect,RetainedWorkPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){observe_heap(run)}
fn bank()->EffectBank{EffectBank::new(Wallet::from_profile(&serde_json::json!({"items":1<<20,"copyBytes":1<<30,"capacityBytes":1<<30,"releaseBytes":1<<30,"depth":1<<20,"fuel":1<<20})))}
fn paid<E:std::fmt::Debug>(bank:&mut EffectBank,demand:RetirementDemand,work:u64,run:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll<RetainedCloneStep,E>)->(RetainedCloneStep,(usize,usize)){let issued=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let((poll,_),heap)=observe(||bank.run(issued,work,run));let RetainedWorkPoll::Complete(turn)=poll else{panic!("original capture step stayed pending")};let step=turn.result.expect("original capture step");bank.post(step.progress(),issued,heap);assert_eq!(bank.take_admitted(),Some(true));(step,heap)}
fn birth(bank:&mut EffectBank,authority:JobPayloadAuthority,cancel:CancelToken)->(OriginalCallerSourceParent,(usize,usize)){let mut authority=Some(authority);let mut cancel=Some(cancel);let mut admission=OriginalCallerSourceAdmission::new();let mut parent=None;
 let(_,a)=paid(bank,OriginalCallerSourceAdmission::prepare_demand(),1,|e|RetainedWorkPoll::Complete(admission.prepare(&mut authority,&mut cancel,e)));
 let(_,b)=paid(bank,OriginalCallerSourceAdmission::backing_demand().unwrap(),OriginalCallerSourceAdmission::backing_work_demand(),|e|RetainedWorkPoll::Complete(admission.admit_backing(e)));
 let(_,c)=paid(bank,OriginalCallerSourceAdmission::publish_demand(),1,|e|RetainedWorkPoll::Complete(admission.publish(&mut parent,e)));
 (parent.expect("original capture Source parent published"),(a.0+b.0+c.0,a.1+b.1+c.1))}
fn now()->Option<u64>{Some(1)}
#[test]
fn original_caller_capture_preserves_paid_aliases_supplier_identity_and_exact_receiving(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️caller.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();let operation=OperationId(policy["operation"].as_u64().unwrap());let generation=Generation(policy["generation"].as_u64().unwrap());let budget=||StepBudget::new(policy["fuel"].as_u64().unwrap(),policy["deadlineUs"].as_u64().unwrap(),grant);
 for cut in policy["captureCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap();let((cancel,root_birth),heap)=observe(||CancelToken::admit_root(grant).result.unwrap().unwrap());assert_eq!(heap,(root_birth.retained_capacity_bytes,0));let mut born=heap.0;let mut released=0;let((authority,ledger_birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant,&mut None).result.unwrap().unwrap());assert_eq!(heap,(ledger_birth.retained_capacity_bytes,0));born+=heap.0;
  let mut bank=bank();let(mut parent,heap)=birth(&mut bank,authority,cancel);born+=heap.0;released+=heap.1;let ledger_pointer=parent.payload_authority_identity().unwrap();let mut sequence=0;
  {let source=&parent;let authority=source.payload_authority().unwrap();let cancel=source.cancellation().unwrap();let mut recipient=Default::default();let context=source.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(mut capture,heap)=observe(||OriginalCallerCapture::begin(authority,cancel,&context).unwrap());assert_eq!(heap,(0,0));drop(context);
  for _ in 0..cut{let mut recipient=Default::default();let mut context=source.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(_,heap)=observe(||capture.advance(&mut context).unwrap());assert_eq!(heap,(0,0));assert_eq!(context.retained_progress(),metadata());assert_eq!(source.payload_authority_identity().unwrap(),ledger_pointer);}
  if cut<2{cancel.cancel_now();for _ in 0..4{if capture.terminal_is_empty(){break}let mut recipient=Default::default();let mut context=source.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(step,heap)=observe(||capture.close_step(&mut context).unwrap());assert_eq!(heap,(0,0));assert_eq!(context.retained_progress(),step.progress());}assert!(capture.terminal_is_empty());assert_eq!(observe(||drop(capture)).1,(0,0));}
  else{let(mut original,mut issuer)=match capture.finish(){Ok(value)=>value,Err(_)=>panic!("funded capture must finish")};let mut recipient=Default::default();let mut context=source.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let pointer=context.original_recipient_identity();let(returned,heap)=observe(||issuer.issue(&original,&mut context).unwrap().close(grant,|same|{assert_eq!(same.original_recipient_identity(),pointer);same.consume_retained(metadata())?;same.consume_fuel(1);Ok(InteractiveJobCloseStep::Pending{progress:metadata()})}));assert_eq!(heap,(0,0));assert!(returned.receipt_refusal().is_none());assert_eq!(context.retained_progress(),metadata());assert_eq!(returned.into_original().unwrap().unwrap().progress(),metadata());drop(context);
   let mut failed_source=None;let failed_progress=RetainedCloneProgress{copied_items:1,retained_capacity_bytes:17,..Default::default()};let mut recipient=Default::default();let mut context=source.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(returned,heap)=observe(||issuer.issue(&original,&mut context).unwrap().close(grant,|same|{let mut source=Vec::<u8>::new();source.try_reserve_exact(17).unwrap();failed_source=Some(source);Err(OriginalTurnFailure::debit_original(ValueError::literal(ValueRefusalKind::InvalidValue,"original capture failed child").with_retained_progress(failed_progress),same))}));assert_eq!(heap,(17,0));born+=heap.0;assert_eq!(context.retained_progress(),failed_progress);let failure=returned.into_original().unwrap().unwrap_err();assert!(failure.receipt_refusal.is_none());assert_eq!(failure.primary.message(),"original capture failed child");assert_eq!(observe(||drop(failure)).1,(0,0));drop(context);
   let mut recipient=Default::default();let mut context=source.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let progress=RetainedCloneProgress{copied_items:1,released_bytes:failed_source.as_ref().unwrap().capacity(),..Default::default()};assert!(progress.fits(context.retained_grant()));let((),heap)=observe(||{context.consume_retained(progress).unwrap();drop(failed_source.take());});assert_eq!(heap,(0,17));released+=heap.1;drop(context);
   let mut recipient=Default::default();let mut context=source.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(returned,heap)=observe(||issuer.issue(&original,&mut context).unwrap().close(grant,|_|Ok(InteractiveJobCloseStep::Pending{progress:metadata()})));assert_eq!(heap,(0,0));assert!(returned.admitted().is_none());assert!(returned.receipt_refusal().is_some());assert_eq!(context.retained_progress(),Default::default());assert_eq!(observe(||drop(returned)).1,(0,0));drop(context);
   let((mut foreign,_),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant,&mut None).result.unwrap().unwrap());born+=heap.0;let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),cancel,now,&mut sequence,&mut recipient,&foreign).unwrap();assert!(issuer.issue(&original,&mut context).is_err());assert_eq!(context.retained_progress(),Default::default());drop(context);for _ in 0..8{if foreign.terminal_is_empty(){break}let(step,heap)=paid(&mut bank,foreign.retirement_demands(),foreign.retirement_work_demand().unwrap(),|e|RetainedWorkPoll::Complete(foreign.close_step(e)));assert_eq!(heap,(0,step.progress().released_bytes));released+=heap.1;}assert!(foreign.terminal_is_empty());assert_eq!(observe(||drop(foreign)).1,(0,0));
   let((foreign_cancel,_),heap)=observe(||CancelToken::admit_root(grant).result.unwrap().unwrap());born+=heap.0;let mut recipient=Default::default();let mut context=StepContext::with_payload_authority(operation,generation,budget(),&foreign_cancel,now,&mut sequence,&mut recipient,authority).unwrap();assert!(issuer.issue(&original,&mut context).is_err());assert_eq!(context.retained_progress(),Default::default());drop(context);let mut foreign_cancel=CancelTokenRetirement::from_token(foreign_cancel);for _ in 0..4{if foreign_cancel.terminal_is_empty(){break}let(step,heap)=paid(&mut bank,foreign_cancel.retirement_demands().unwrap(),foreign_cancel.retirement_work_demand(),|e|RetainedWorkPoll::Complete(foreign_cancel.close_step(e)));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.1;}assert!(foreign_cancel.terminal_is_empty());assert_eq!(observe(||drop(foreign_cancel)).1,(0,0));
   cancel.cancel_now();for _ in 0..4{if original.terminal_is_empty(){break}let mut recipient=Default::default();let mut context=source.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(step,heap)=observe(||original.close_step(&mut issuer,&mut context).unwrap());assert_eq!(heap,(0,0));assert_eq!(context.retained_progress(),step.progress());}assert!(original.terminal_is_empty());assert_eq!(observe(||drop(original)).1,(0,0));
  }}
  for _ in 0..64{if parent.terminal_is_empty(){break}let(step,heap)=paid(&mut bank,parent.retirement_demands().unwrap(),parent.retirement_work_demand().unwrap(),|e|parent.close_step(e));assert_eq!(heap.0,step.progress().retained_capacity_bytes);released+=heap.1;}assert!(parent.terminal_is_empty());assert_eq!(observe(||drop(parent)).1,(0,0));assert_eq!(born,released);
 }
}

fn metadata()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,..Default::default()}}
fn observe_heap<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
